pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address initialOwner = c.owner();
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        try c.transferOwnership(address(0)) { assertTrue(c.owner() == newOwner, "owner should not change to zero"); } catch { }
    }
}
